public with sharing class AccountScoringJob implements Queueable {
    private static final Integer BATCH_SIZE = 200;
    private static final Integer DEFAULT_MAX_STACK_DEPTH = 255;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds != null ? accountIds.clone() : new List<Id>();
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return enqueue(accountIds);
    }

    public void execute(QueueableContext context) {
        if (this.accountIds == null || this.accountIds.isEmpty()) {
            return;
        }

        List<Id> remainingIds = this.accountIds.clone();
        List<Id> currentBatchIds = new List<Id>();
        Integer count = Math.min(BATCH_SIZE, remainingIds.size());
        for (Integer i = 0; i < count; i++) {
            currentBatchIds.add(remainingIds.remove(0));
        }

        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentBatchIds
        ];

        for (Account acc : accountsToUpdate) {
            if (acc.AnnualRevenue == null || acc.AnnualRevenue < 100000) {
                acc.Rating = 'Cold';
            } else if (acc.AnnualRevenue >= 1000000) {
                acc.Rating = 'Hot';
            } else {
                acc.Rating = 'Warm';
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }

        if (!remainingIds.isEmpty()) {
            enqueue(remainingIds);
        }
    }

    private static Id enqueue(List<Id> ids) {
        AccountScoringJob job = new AccountScoringJob(ids);
        if (!AsyncInfo.hasMaxStackDepth()) {
            AsyncOptions options = new AsyncOptions();
            Integer requiredDepth = (ids.size() + BATCH_SIZE - 1) / BATCH_SIZE + 1;
            options.MaximumQueueableStackDepth = Math.max(DEFAULT_MAX_STACK_DEPTH, requiredDepth);
            return System.enqueueJob(job, options);
        }
        return System.enqueueJob(job);
    }
}
