                ? (Opportunity) existingRecords.get(opp.Id)
                : null;
            if (
                existingOpp != null &&
                existingOpp.StageName == CLOSED_WON_STAGE &&
                opp.Amount != existingOpp.Amount
            ) {
                opp.Amount.addError(error(WON_AMOUNT_CHANGE_ERROR, opp, Opportunity.Amount));
            }
        }
