public with sharing class RecordAccessService {
    private static final Integer MAX_IDS_PER_QUERY = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        Id currentUserId = UserInfo.getUserId();
        List<Id> currentBatch = new List<Id>();

        for (Id recordId : recordIds) {
            if (recordId == null) {
                continue;
            }
            currentBatch.add(recordId);
            if (currentBatch.size() == MAX_IDS_PER_QUERY) {
                editableRecordIds.addAll(queryEditableIds(currentUserId, currentBatch));
                currentBatch.clear();
            }
        }

        if (!currentBatch.isEmpty()) {
            editableRecordIds.addAll(queryEditableIds(currentUserId, currentBatch));
        }

        return editableRecordIds;
    }

    private static Set<Id> queryEditableIds(Id userId, List<Id> batch) {
        Set<Id> editable = new Set<Id>();
        for (UserRecordAccess access : [
            SELECT RecordId
            FROM UserRecordAccess
            WHERE UserId = :userId
                AND RecordId IN :batch
                AND HasEditAccess = true
        ]) {
            editable.add(access.RecordId);
        }
        return editable;
    }
}
